<?php
declare(strict_types=1);
if(!defined('ACADEMY_ROOT')){http_response_code(403);exit;}

// Deliberately plausible alternatives. Facts are revealed only by the reply the
// learner actually hears. Critical promises remain failures regardless of score.
function academy_call_challenge(string $id,int $variant): array
{
    $meta=academy_call_catalog()[$id]??null;
    if(!$meta||!in_array($variant,[0,1],true))throw new InvalidArgumentException('Άγνωστο σενάριο.');
    $f='academy_call_field';$nodes=[];$fields=[];$o='academy_call_option';
    $stages=['pending'=>'Εκκρεμούν ουσιώδη στοιχεία','review'=>'Εσωτερική επαλήθευση, όχι έγκριση','closed'=>'Κλειστό — μη νέα προσέγγιση','approved'=>'Εγκεκριμένο lead','won'=>'Ολοκληρωμένη συμφωνία'];
    $yesno=['yes'=>'Ναι, μόνο για το συμφωνημένο βήμα','no'=>'Όχι','pending'=>'Δεν επιβεβαιώθηκε'];
    $city=$variant?'Κοζάνη':'Λάρισα';$company='Demo '.$city.' · Συνθετικό περιστατικό';
    // Each row: prompt; best reply/response/facts; incomplete alternatives; unsafe alternative.
    $add=function(string $key,string $prompt,string $next,array $a,array $b,array $c,array $d)use(&$nodes,$o):void{
        $options=[];foreach(['a'=>$a,'b'=>$b,'c'=>$c,'d'=>$d] as $choice=>$v){
            $options[$choice]=$o($v[0],$v[1],$v[2],$v[5]??$next,$v[3]??[],$v[4]??false);
        }
        $nodes[$key]=compact('prompt','options');
    };
    if($id==='panels'){
        $qty=$variant?2400:3200;$watts=$variant?310:280;$unit=$variant?9:8.5;$paid=$variant?1500:2000;
        $fields=[
            'authority'=>$f('Αρμοδιότητα','mandated','select',['mandated'=>'Εξουσιοδοτημένη εκπρόσωπος, όχι ιδιοκτήτρια','owner'=>'Ιδιοκτήτρια','pending'=>'Εκκρεμεί επιβεβαίωση'],true),
            'quantity'=>$f('Συγκεκριμένη διαθέσιμη παρτίδα (πάνελ)',(string)$qty,'number'),
            'watts'=>$f('Ονομαστική ισχύς ανά πάνελ (W)',(string)$watts,'number'),
            'location'=>$f('Τοποθεσία',$city),
            'unit_price'=>$f('Ζητούμενη τιμή ανά πάνελ (€)',(string)$unit,'number'),
            'total_price'=>$f('Ζητούμενη αξία συγκεκριμένης παρτίδας (€)',(string)($qty*$unit),'number'),
            'paid_panels'=>$f('Πάνελ πληρωμένα στον πωλητή',(string)$paid,'number'),
            'commission'=>$f('Προμήθεια πάνελ που έχει καταστεί πληρωτέα (€)',(string)($paid*.6),'number',[],true),
            'consent'=>$f('Άδεια συνέχειας','yes','select',$yesno,true),
            'stage'=>$f('Στάδιο lead','review','select',$stages,true),
            'next_step'=>$f('Επόμενη ενέργεια','verify','select',['verify'=>'Έλεγχος εντολής, εξοπλισμού και παραστατικών πληρωμής','pay'=>'Άμεση πληρωμή προμήθειας για όλη τη συμφωνία','sale'=>'Αναμονή μεταπώλησης πριν από κάθε προμήθεια'],true)
        ];
        $add('open','Έχω τέσσερα λεπτά. Μου έχουν ξανατηλεφωνήσει για τα ίδια πάνελ. Πριν πω οτιδήποτε, γιατί να μιλήσουμε;','authority',
            ['Θα περιοριστώ στο αν υπάρχει συγκεκριμένη διαθέσιμη παρτίδα και κατάλληλος υπεύθυνος. Αν έχει ήδη προχωρήσει η συζήτηση, θα ελέγξουμε πρώτα την υπάρχουσα επαφή.','Εντάξει, σύντομα. Έχω μιλήσει με άλλη εταιρεία, όχι με τη δική σας.',10],
            ['Ας στείλουμε πρώτα την εταιρική παρουσίαση και ας κρατήσουμε την ποσότητα για την επόμενη επικοινωνία.','Σήμερα μπορώ να δώσω στοιχεία. Δεν έχω δεσμευτεί όμως ότι θέλω άλλο τηλεφώνημα.',4],
            ['Θα ανοίξω νέα καρτέλα για να μη χαθεί χρόνος και θα ελέγξουμε αργότερα αν υπάρχει προηγούμενη συζήτηση.','Θέλω έναν υπεύθυνο, όχι παράλληλα τηλεφωνήματα από την ίδια εταιρεία.',2],
            ['Μπορούμε να δεσμεύσουμε την παρτίδα στην τιμή αγοράς μας μόλις μου δώσετε το πλήθος.','Δεν έχει προηγηθεί κανένας έλεγχος. Δεν δέχομαι ότι συμφωνήσαμε αγορά.',0,[],true]);
        $add('authority','Το πάρκο δεν είναι στο όνομά μου. Εγώ οργανώνω την αντικατάσταση και μπορώ να σας στείλω φωτογραφίες.','quantity',
            ['Η διαχείριση του έργου και η εντολή πώλησης είναι διαφορετικά. Έχετε εντολή του ιδιοκτήτη για διαπραγμάτευση αυτής της παρτίδας;','Ναι, έχω έγγραφη εντολή διαπραγμάτευσης από τον ιδιοκτήτη. Θα τη στείλω στον υπεύθυνό σας· δεν είμαι η ιδιοκτήτρια.',10,['authority']],
            ['Αρκεί ότι οργανώνετε την αντικατάσταση. Θα ζητήσουμε τα στοιχεία τιμολόγησης όταν φτάσουμε στην αγορά.','Ο ρόλος μου στο έργο δεν σας δίνει από μόνος του εξουσιοδότηση πώλησης.',3],
            ['Ας συνεχίσουμε με τις φωτογραφίες και θα καταγράψουμε ότι η εξουσιοδότηση εκκρεμεί.','Μπορούμε, αλλά θα λείπει ένα ουσιώδες στοιχείο.',5],
            ['Θα σας καταχωρίσω ως ιδιοκτήτρια προς το παρόν για να προχωρήσει ο έλεγχος.','Δεν είμαι ιδιοκτήτρια. Μην το καταγράψετε έτσι.',0,[],true]);
        $add('quantity','Στο πάρκο υπάρχουν περίπου πέντε χιλιάδες πάνελ, αλλά δεν αφαιρούνται όλα στην ίδια φάση.','specs',
            ['Πόσα αφορούν τη συγκεκριμένη διαθέσιμη παρτίδα και ποια είναι απλώς μελλοντικός σχεδιασμός;',"Η παρούσα παρτίδα είναι $qty πάνελ. Τα υπόλοιπα δεν προσφέρονται τώρα. Για αυτή την παρτίδα υπάρχει απόφαση πώλησης.",10,['quantity']],
            ['Θα κρατήσω τα πέντε χιλιάδες ως εκτίμηση του lead και θα διορθωθεί το πλήθος μετά.','Αυτό περιλαμβάνει εξοπλισμό που δεν διαθέτουμε προς πώληση.',2],
            ['Να σημειώσω μόνο ότι πρόκειται για επαγγελματική ποσότητα και να ζητήσουμε αναλυτικό κατάλογο;','Μπορείτε, αλλά δεν θα έχετε συγκεκριμένη ποσότητα ακόμη.',5],
            ['Ας θεωρήσουμε όλο το πάρκο διαθέσιμο, με επιφύλαξη στο τέλος της προσφοράς.','Δεν εξουσιοδοτώ προσφορά για ολόκληρο το πάρκο.',0,[],true]);
        $add('specs','Έχω έναν παλιό κατάλογο και μερικές πρόσφατες φωτογραφίες. Σας κάνουν;','price',
            ['Χρειαζόμαστε να αντιστοιχούν στην τωρινή παρτίδα: πινακίδα ισχύος, κατάσταση, ηλικία και τοποθεσία. Ποια γνωρίζετε ήδη; ',"Η παρτίδα είναι στη $city, $watts Watt ανά πάνελ, εγκατάσταση του 2015. Δεν υπάρχει πρόσφατος εργαστηριακός έλεγχος. Μοντέλο θα επιβεβαιώσουμε από τις πινακίδες.",10,['watts','location']],
            ['Στείλτε μόνο την καλύτερη φωτογραφία. Ο αναλυτικός έλεγχος μπορεί να γίνει αφού κλείσουμε την τιμή.','Η φωτογραφία δεν τεκμηριώνει χαρακτηριστικά ή απόδοση όλης της παρτίδας.',3],
            ['Ας κρατήσουμε τον παλιό κατάλογο ως υπόθεση και να τον επιβεβαιώσουμε αργότερα.','Μην τον παρουσιάσετε ως επιβεβαιωμένα χαρακτηριστικά των σημερινών πάνελ.',5],
            ['Η όψη αρκεί για να τα χαρακτηρίσουμε όλα πλήρως λειτουργικά.','Δεν σας έχω δώσει μέτρηση που να στηρίζει αυτόν τον χαρακτηρισμό.',0,[],true]);
        $add('price','Θέλω να ξέρω σήμερα αν η τιμή είναι εντός αγοράς. Αν την αποδεχτείτε, θα σταματήσω να μιλάω με άλλους.','payment',
            ['Μπορώ να καταγράψω ζητούμενη τιμή, όχι να δεσμεύσω αποδοχή. Είναι τιμή ανά πάνελ ή σύνολο και περιλαμβάνει αποξήλωση ή μεταφορικά;',"Ζητάμε $unit ευρώ ανά πάνελ για τη συγκεκριμένη παρτίδα, χωρίς μεταφορικά ή αποξήλωση. Περιμένω τον έλεγχό σας, όχι προφορική αποδοχή.",10,['unit_price','total_price']],
            ['Ας γράψουμε μία συνολική εκτίμηση και η ομάδα θα βρει μετά αν η τιμή αφορά τεμάχιο ή έργο.','Θέλω να συγκρίνουμε το ίδιο αντικείμενο. Έτσι μπορεί να δημιουργηθεί παρανόηση.',2],
            ['Μπορώ να τη χαρακτηρίσω ενδεικτικά ενδιαφέρουσα πριν μάθω τους όρους και να επανέλθω.','Χρειάζομαι συγκεκριμένη καταγραφή των όρων, όχι ένα γενικό ενδιαφέρον.',4],
            ['Δεχόμαστε την τιμή με την προϋπόθεση να μας κρατήσετε την παρτίδα μέχρι αύριο.','Αυτό ακούγεται ως δέσμευση αγοράς χωρίς εξουσιοδότηση.',0,[],true]);
        $add('payment','Σε προηγούμενη παρτίδα του ίδιου συνεργάτη υπογράφηκε συμφωνία για όλη την ποσότητα. Ζητά την προμήθεια για όλα τα τεμάχια τώρα.','consent',
            ['Η συμφωνία μόνη της δεν αρκεί. Πόσα τεμάχια έχουν πραγματικά αγοραστεί και πληρωθεί στον πωλητή;',"Για $paid πάνελ έχει εξοφληθεί ο πωλητής. Για τα υπόλοιπα υπάρχει συμφωνία, αλλά καμία πληρωμή ακόμη. Τα παραστατικά θα ελεγχθούν.",10,['paid_panels','commission']],
            ['Να κρατήσουμε ολόκληρη την προμήθεια μέχρι να ολοκληρωθεί η μεταπώληση;','Η αμοιβή αγοράς δεν εξαρτάται από τη μεταπώληση. Χρειάζεται έλεγχος της πληρωμένης ποσότητας.',3],
            ['Θα βασιστούμε στην αρχική εκτίμηση ποσότητας και θα κάνουμε συμψηφισμό αργότερα.','Η εκτίμηση δεν αποδεικνύει τι αγοράστηκε και τι πληρώθηκε.',2],
            ['Αφού υπογράφηκε η συμφωνία, ενεργοποιείται το σύνολο των εξήντα λεπτών ανά πάνελ.','Δεν έχει εξοφληθεί όλη η ποσότητα. Αυτό θα δημιουργούσε λάθος υποχρέωση.',0,[],true]);
        $add('consent','Θα σας δώσω στοιχεία αλλά δεν θέλω μαζικά μηνύματα και κλήσεις από όποιον βρει το email μου.','close',
            ['Να διαβιβάσω τα στοιχεία στον αρμόδιο της Melas μόνο για έλεγχο αυτής της παρτίδας και μία συνεννόηση μαζί σας;','Ναι, για αυτή την παρτίδα και τον συγκεκριμένο υπεύθυνο. Όχι για γενικές προωθητικές ενέργειες.',10,['consent']],
            ['Αφού δώσατε email, θα θεωρήσουμε διαθέσιμη και τηλέφωνο και μελλοντική ενημέρωση.','Δεν έδωσα γενική άδεια προσέγγισης.',0,[],true],
            ['Ας αφήσουμε αδιευκρίνιστο το κανάλι και θα αποφασίσει ο υπεύθυνος.','Θέλω να ξέρω σε τι συμφωνώ πριν διαβιβαστούν τα στοιχεία.',3],
            ['Θα τα κρατήσω προσωπικά και θα μιλήσω ως ιδιώτης αντί για την εταιρεία.','Η επικοινωνία μας αφορά την εταιρεία, όχι μια παράλληλη ιδιωτική συμφωνία.',0,[],true]);
        $add('close','Άρα το lead εγκρίθηκε και ο συνεργάτης έχει ήδη τα ογδόντα ευρώ;','crm',
            ['Όχι από τη δική μου καταχώριση. Θα ελεγχθούν όλα τα στοιχεία, τα εμπορικά κριτήρια και η πραγματική ευκαιρία από εξουσιοδοτημένο υπεύθυνο.','Σωστά. Θα στείλω εντολή, πινακίδες και παραστατικά για τον εσωτερικό έλεγχο.',10,['next_step']],
            ['Να το κρατήσουμε ως εγκεκριμένο με σημείωση ότι περιμένουμε αρχεία.','Η σημείωση δεν υποκαθιστά την απαιτούμενη επαλήθευση.',0,[],true],
            ['Ας περιμένουμε να πουληθούν τα πάνελ πριν αναγνωριστεί ακόμη και η αμοιβή του qualified lead.','Η αμοιβή έγκυρου εγκεκριμένου lead δεν εξαρτάται από τελική αγορά ή μεταπώληση.',3],
            ['Θα στείλω στον συνεργάτη μια προφορική έγκριση για να μη χαθεί το κίνητρο.','Χρειάζεται πραγματική και καταγεγραμμένη έγκριση, όχι προσδοκία.',0,[],true]);
        $required=['authority','quantity','watts','location','consent','next_step'];
    } else {
        // Common 8-decision architecture; each company has its own commercial case.
        require_once __DIR__.'/call-business-v34.php';
        return academy_call_business_challenge($id,$variant,$meta,$f,$add,$nodes,$stages,$yesno,$city);
    }
    $intro=$nodes['open']['prompt'];
    return $meta+compact('id','variant','company','intro','nodes','fields','required')+['start'=>'open','max_dialogue'=>80];
}
